        setAge(getRandom().nextInt(getMaxAge()));
        setFoodLevel(getRandom().nextInt(foodCap));
    } else {
        setAge(0);
        setFoodLevel(foodCap - baseFoodValue);
    }
    setGrowthLevel(getAge() / growthDivisor);
}

